class Solution {public long solve(int required,int[] people){if(required==0)return 0;int size=Integer.highestOneBit(required)<<1;int[] dp=new int[size],active=new int[size];Arrays.fill(dp,100);dp[0]=0;int count=1;for(int person:people){int mask=person&required;if(mask==0)continue;int before=count;for(int i=0;i<before;i++){int state=active[i],next=state|mask,cost=dp[state]+1;if(dp[next]==100)active[count++]=next;if(cost<dp[next])dp[next]=cost;}}return dp[required]==100?-1:dp[required];}}